    <header class="demo-header">
      <div class="demo-header-inner examples-header-inner">
        <div class="demo-logo">
          <span class="demo-logo-text">XDoc PPTX Viewer SDK</span>
        </div>
        <div class="demo-file-info examples-file-info">
          <span class="demo-file-name" data-file-name>No file loaded</span>
          <div class="examples-framework-menu" data-framework-menu>
            <button class="demo-btn demo-btn-ghost examples-framework-trigger" type="button" data-framework-trigger aria-haspopup="menu" aria-expanded="false">
              <span>Framework</span>
              <strong data-framework-label>Vanilla JS</strong>
            </button>
            <div class="examples-framework-panel" data-framework-menu-panel role="menu" hidden></div>
          </div>
          <button class="demo-btn demo-btn-ghost examples-src-toggle" type="button" data-src-toggle aria-expanded="false">SRC</button>
          <button class="demo-btn demo-btn-ghost" type="button" data-sample>Load SDK sample</button>
          <button class="demo-btn demo-btn-ghost" type="button" data-fixture>Load real fixture</button>
          <button class="demo-btn demo-btn-ghost" type="button" data-reset>Reset</button>
          <button class="demo-btn demo-btn-primary" type="button" data-pdf disabled>Export PDF</button>
        </div>
      </div>
    </header>
